//! Predictor verification tests.
//!
//! Hand-computed inputs only — expected values are worked out from the
//! spec, not generated by the implementation under test.
//!
//! PNG filters are applied per row; each row is prefixed by a filter
//! byte (0=None, 1=Sub, 2=Up, 3=Average, 4=Paeth). The predictor value
//! in `/DecodeParms` selects the *set* of filters: 10–14 fix the filter
//! (None/Sub/Up/Average/Paeth respectively), 15 = "optimum" (per-row
//! filter byte chooses).

use flate2::write::ZlibEncoder;
use flate2::Compression;
use kasane_pdf::{Document, Error, Limits};
use std::io::Write;

/// Build a 1-page PDF whose /Contents is a Flate stream with the given
/// decoded bytes and DecodeParms.
fn pdf_with_flate(decoded: &[u8], decode_parms: &str) -> Vec<u8> {
    let comp = {
        let mut e = ZlibEncoder::new(Vec::new(), Compression::default());
        e.write_all(decoded).unwrap();
        e.finish().unwrap()
    };
    let mut data = Vec::new();
    data.extend_from_slice(b"%PDF-1.4\n");
    let mut offsets = Vec::new();
    let bodies = [
        (1, b"<< /Type /Catalog /Pages 2 0 R >>".to_vec()),
        (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>".to_vec()),
        (
            3,
            b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R >>".to_vec(),
        ),
        (
            4,
            [
                format!(
                    "<< /Length {} /Filter /FlateDecode /DecodeParms {} >>\nstream\n",
                    comp.len(),
                    decode_parms
                )
                .into_bytes(),
                comp.clone(),
            ]
            .concat(),
        ),
    ];
    for (n, b) in &bodies {
        offsets.push((*n, data.len()));
        data.extend_from_slice(format!("{n} 0 obj\n").as_bytes());
        data.extend_from_slice(b);
        if *n == 4 {
            data.extend_from_slice(b"\nendstream\nendobj\n");
        } else {
            data.extend_from_slice(b"\nendobj\n");
        }
    }
    let xref = data.len();
    data.extend_from_slice(b"xref\n0 5\n");
    data.extend_from_slice(b"0000000000 65535 f \n");
    for (_n, off) in &offsets {
        data.extend_from_slice(format!("{off:010} 00000 n \n").as_bytes());
    }
    data.extend_from_slice(b"trailer\n<< /Size 5 /Root 1 0 R >>\n");
    data.extend_from_slice(format!("startxref\n{xref}\n%%EOF\n").as_bytes());
    data
}

fn decode_contents(pdf: &[u8]) -> Result<Vec<u8>, Error> {
    let doc = Document::from_bytes(pdf)?;
    let contents = doc.page_contents(&doc.pages()[0])?;
    assert_eq!(contents.len(), 1);
    Ok(contents.into_iter().next().unwrap())
}

// -------------------------------------------------------------------
// PNG predictors (10–15)
// -------------------------------------------------------------------

/// Predictor 10 = "none": every row's filter byte is 0 and data passes
/// through unchanged.
#[test]
fn png_predictor_10_none() {
    // 2 rows, 1 column, 1 color: [filter][b] twice.
    let decoded = b"\x00\xAA\x00\xBB"; // row0: None,0xAA; row1: None,0xBB
    let pdf = pdf_with_flate(decoded, "<< /Predictor 10 /Colors 1 /Columns 1 >>");
    let out = decode_contents(&pdf).unwrap();
    assert_eq!(out, b"\xAA\xBB");
}

/// Predictor 11 = Sub: byte i += byte i-bpp. With Colors=1 bpp=1, a row
/// of deltas becomes a prefix-sum.
#[test]
fn png_predictor_11_sub() {
    // Columns=3, Colors=1: row = [filter][d0][d1][d2]
    // Sub: b0=d0, b1=d0+d1, b2=b1+d2
    // d = [10, 5, 3] -> out [10, 15, 18]
    let decoded = b"\x01\x0A\x05\x03";
    let pdf = pdf_with_flate(decoded, "<< /Predictor 11 /Colors 1 /Columns 3 >>");
    let out = decode_contents(&pdf).unwrap();
    assert_eq!(out, &[10, 15, 18]);
}

/// Predictor 12 = Up: byte i += byte i of previous row (same column).
#[test]
fn png_predictor_12_up() {
    // 2 rows, 2 cols, 1 color. Row0 filter=2(Up): out = in (prev=0).
    // Row1 filter=2(Up): out = in + prev_row.
    let decoded = b"\x02\x10\x20\x02\x01\x02"; // [f2 d0 d1][f2 d0 d1]
    let pdf = pdf_with_flate(decoded, "<< /Predictor 12 /Colors 1 /Columns 2 >>");
    let out = decode_contents(&pdf).unwrap();
    assert_eq!(out, &[0x10, 0x20, 0x11, 0x22]);
}

/// Predictor 13 = Average: byte i += floor((left + up)/2).
#[test]
fn png_predictor_13_average() {
    // 1 row, 2 cols, 1 color. bpp=1.
    // i=0: a=0 (no left), b=0 (no prev) -> avg=0 -> out=raw
    // i=1: a=out[0], b=0 -> avg=out[0]/2 -> out[1]=raw+avg
    let decoded = b"\x03\x10\x06"; // filter 3, raw [0x10, 0x06]
    let pdf = pdf_with_flate(decoded, "<< /Predictor 13 /Colors 1 /Columns 2 >>");
    let out = decode_contents(&pdf).unwrap();
    // i=0: out0 = 0x10 + 0 = 0x10
    // i=1: out1 = 0x06 + floor((0x10 + 0)/2) = 0x06 + 0x08 = 0x0E
    assert_eq!(out, &[0x10, 0x0E]);
}

/// Predictor 14 = Paeth: byte i += Paeth(left, up, upper-left).
#[test]
fn png_predictor_14_paeth() {
    // 1 row, 2 cols, 1 color. bpp=1.
    // i=0: a=0,b=0,c=0 -> p=0 -> pa=pb=pc=0 -> a chosen -> out=raw
    // i=1: a=out[0],b=0,c=0 -> p=a -> pa=0,pb=a,pc=a -> choose a -> out[1]=raw+a
    let decoded = b"\x04\x10\x06"; // filter 4, raw [0x10, 0x06]
    let pdf = pdf_with_flate(decoded, "<< /Predictor 14 /Colors 1 /Columns 2 >>");
    let out = decode_contents(&pdf).unwrap();
    // i=0: out0 = 0x10
    // i=1: out1 = 0x06 + 0x10 = 0x16
    assert_eq!(out, &[0x10, 0x16]);
}

/// Predictor 15 = optimum: the filter byte of each row chooses.
#[test]
fn png_predictor_15_mixed_rows() {
    // Row0 uses filter 0 (None), row1 uses filter 2 (Up).
    // Row0 data [0x10,0x20]; Row1 data [0x01,0x02] + Up prev row ->
    // [0x10+1, 0x20+2] = [0x11, 0x22]
    let decoded = b"\x00\x10\x20\x02\x01\x02"; // [f0 d0 d1][f2 d0 d1]
    let pdf = pdf_with_flate(decoded, "<< /Predictor 15 /Colors 1 /Columns 2 >>");
    let out = decode_contents(&pdf).unwrap();
    assert_eq!(out, &[0x10, 0x20, 0x11, 0x22]);
}

/// Multi-column, multi-color: bpp = Colors (1 byte/component).
#[test]
fn png_predictor_multi_color() {
    // Columns=2, Colors=3 -> bpp=3, row_len=6. 1 row, filter 1 (Sub):
    // raw bytes d[0..5]; out[i] = d[i] + d[i-3] for i>=3.
    let decoded = b"\x01\x01\x02\x03\x10\x20\x30";
    let pdf = pdf_with_flate(decoded, "<< /Predictor 11 /Colors 3 /Columns 2 >>");
    let out = decode_contents(&pdf).unwrap();
    // i<3: out=raw = [1,2,3]
    // i=3: out = 0x10 + out[0]=1 -> 0x11
    // i=4: out = 0x20 + out[1]=2 -> 0x22
    // i=5: out = 0x30 + out[2]=3 -> 0x33
    assert_eq!(out, &[1, 2, 3, 0x11, 0x22, 0x33]);
}

/// First-byte boundary: bpp applies to the left-neighbour only; the
/// very first byte of a row has no left.
#[test]
fn png_predictor_first_byte_boundary() {
    // Columns=1, Colors=2 -> bpp=2, row_len=2. Filter 1 (Sub):
    // only bytes i>=2 are filtered; i<2 pass through.
    let decoded = b"\x01\xAA\xBB";
    let pdf = pdf_with_flate(decoded, "<< /Predictor 11 /Colors 2 /Columns 1 >>");
    let out = decode_contents(&pdf).unwrap();
    assert_eq!(out, b"\xAA\xBB");
}

// -------------------------------------------------------------------
// TIFF predictor (2)
// -------------------------------------------------------------------

/// TIFF predictor 2: horizontal differencing, no per-row filter byte.
/// 8-bit wraparound arithmetic.
#[test]
fn tiff_predictor_2_basic() {
    // Columns=3, Colors=1: deltas [10,5,3] -> out [10,15,18]
    let decoded = &[10u8, 5, 3];
    let pdf = pdf_with_flate(decoded, "<< /Predictor 2 /Colors 1 /Columns 3 >>");
    let out = decode_contents(&pdf).unwrap();
    assert_eq!(out, &[10, 15, 18]);
}

/// 8-bit wraparound: 250 + 10 wraps to 4.
#[test]
fn tiff_predictor_2_wraparound() {
    let decoded = &[250u8, 10, 1]; // deltas
    let pdf = pdf_with_flate(decoded, "<< /Predictor 2 /Colors 1 /Columns 3 >>");
    let out = decode_contents(&pdf).unwrap();
    // i0: 250; i1: 250+10=260 -> wraps to 4; i2: 4+1=5
    assert_eq!(out, &[250, 4, 5]);
}

/// Multi-row TIFF: no filter byte; rows are contiguous.
#[test]
fn tiff_predictor_2_multi_row() {
    let decoded = &[10u8, 5, 100, 5]; // 2 rows of 2 cols
    let pdf = pdf_with_flate(decoded, "<< /Predictor 2 /Colors 1 /Columns 2 >>");
    let out = decode_contents(&pdf).unwrap();
    // row0: [10, 10+5=15]; row1: [100, 100+5=105]
    assert_eq!(out, &[10, 15, 100, 105]);
}

