/// Predictor 1 (default / absent DecodeParms): no predictor processing.
#[test]
fn predictor_1_is_passthrough() {
    let decoded = b"raw data unchanged";
    let pdf = pdf_with_flate(decoded, "<< /Predictor 1 >>");
    let out = decode_contents(&pdf).unwrap();
    assert_eq!(out, decoded);
}

/// No DecodeParms at all: Predictor defaults to 1 -> passthrough.
#[test]
fn no_decode_parms_passthrough() {
    let decoded = b"no parms at all";
    let mut data = Vec::new();
    data.extend_from_slice(b"%PDF-1.4\n");
    let mut offsets = Vec::new();
    let comp = {
        let mut e = ZlibEncoder::new(Vec::new(), Compression::default());
        e.write_all(decoded).unwrap();
        e.finish().unwrap()
    };
    let bodies = [
        (1, b"<< /Type /Catalog /Pages 2 0 R >>".to_vec()),
        (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>".to_vec()),
        (
            3,
            b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R >>".to_vec(),
        ),
        (
            4,
            [
                format!(
                    "<< /Length {} /Filter /FlateDecode >>\nstream\n",
                    comp.len()
                )
                .into_bytes(),
                comp.clone(),
            ]
            .concat(),
        ),
    ];
    for (n, b) in &bodies {
        offsets.push((*n, data.len()));
        data.extend_from_slice(format!("{n} 0 obj\n").as_bytes());
        data.extend_from_slice(b);
        if *n == 4 {
            data.extend_from_slice(b"\nendstream\nendobj\n");
        } else {
            data.extend_from_slice(b"\nendobj\n");
        }
    }
    let xref = data.len();
    data.extend_from_slice(b"xref\n0 5\n");
    data.extend_from_slice(b"0000000000 65535 f \n");
    for (_n, off) in &offsets {
        data.extend_from_slice(format!("{off:010} 00000 n \n").as_bytes());
    }
    data.extend_from_slice(b"trailer\n<< /Size 5 /Root 1 0 R >>\n");
    data.extend_from_slice(format!("startxref\n{xref}\n%%EOF\n").as_bytes());
    let out = decode_contents(&data).unwrap();
    assert_eq!(out, decoded);
}

/// /DecodeParms null entry in a filter array means "no parms".
#[test]
fn decode_parms_null_entry() {
    let decoded = b"hi";
    // Two filters: /Filter [/F1 /F2] means data was encoded by F2 then
    // F1.  For two FlateDecodes, we must double-compress: decode with
    // F1 (first) then F2 (second).  Both parms are null.
    let comp = {
        let mut e = ZlibEncoder::new(Vec::new(), Compression::default());
        e.write_all(decoded).unwrap();
        let once = e.finish().unwrap();
        // Encode again for the second filter layer.
        let mut e2 = ZlibEncoder::new(Vec::new(), Compression::default());
        e2.write_all(&once).unwrap();
        e2.finish().unwrap()
    };
    let mut data = Vec::new();
    data.extend_from_slice(b"%PDF-1.4\n");
    let mut offsets = Vec::new();
    let bodies = [
        (1, b"<< /Type /Catalog /Pages 2 0 R >>".to_vec()),
        (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>".to_vec()),
        (
            3,
            b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R >>".to_vec(),
        ),
        (
            4,
            [
                format!(
                    "<< /Length {} /Filter [/FlateDecode /FlateDecode] /DecodeParms [null null] >>\nstream\n",
                    comp.len()
                )
                .into_bytes(),
                comp.clone(),
            ]
            .concat(),
        ),
    ];
    for (n, b) in &bodies {
        offsets.push((*n, data.len()));
        data.extend_from_slice(format!("{n} 0 obj\n").as_bytes());
        data.extend_from_slice(b);
        if *n == 4 {
            data.extend_from_slice(b"\nendstream\nendobj\n");
        } else {
            data.extend_from_slice(b"\nendobj\n");
        }
    }
    let xref = data.len();
    data.extend_from_slice(b"xref\n0 5\n");
    data.extend_from_slice(b"0000000000 65535 f \n");
    for (_n, off) in &offsets {
        data.extend_from_slice(format!("{off:010} 00000 n \n").as_bytes());
    }
    data.extend_from_slice(b"trailer\n<< /Size 5 /Root 1 0 R >>\n");
    data.extend_from_slice(format!("startxref\n{xref}\n%%EOF\n").as_bytes());
    let out = decode_contents(&data).unwrap();
    assert_eq!(out, decoded);
}

// -------------------------------------------------------------------
// Error cases
// -------------------------------------------------------------------

/// Row-length mismatch: data not a multiple of stride.
#[test]
fn png_predictor_bad_row_length() {
    // Columns=2,Colors=1 -> stride=3; data len 5 is not a multiple.
    let decoded = b"\x00\x01\x02\x00\x03";
    let pdf = pdf_with_flate(decoded, "<< /Predictor 15 /Colors 1 /Columns 2 >>");
    let err = decode_contents(&pdf).unwrap_err();
    assert!(matches!(err, Error::Parse(_)), "got: {err:?}");
}

/// Invalid row filter byte (5+).
#[test]
fn png_predictor_bad_row_filter() {
    let decoded = b"\x07\x01\x02"; // filter 7 invalid
    let pdf = pdf_with_flate(decoded, "<< /Predictor 15 /Colors 1 /Columns 2 >>");
    let err = decode_contents(&pdf).unwrap_err();
    assert!(matches!(err, Error::Parse(_)), "got: {err:?}");
}

/// Unsupported BitsPerComponent.
#[test]
fn unsupported_bits_per_component() {
    let decoded = b"\x00\x01";
    let pdf = pdf_with_flate(
        decoded,
        "<< /Predictor 15 /Colors 1 /BitsPerComponent 4 /Columns 1 >>",
    );
    let err = decode_contents(&pdf).unwrap_err();
    assert!(matches!(err, Error::Unsupported { .. }), "got: {err:?}");
}

/// Unsupported predictor value (e.g. 9 is not a valid predictor).
#[test]
fn unsupported_predictor_value() {
    let decoded = b"\x00\x01";
    let pdf = pdf_with_flate(decoded, "<< /Predictor 9 /Colors 1 /Columns 1 >>");
    let err = decode_contents(&pdf).unwrap_err();
    assert!(matches!(err, Error::Unsupported { .. }), "got: {err:?}");
}

/// Predictor output exceeding the per-stream limit.
#[test]
fn predictor_output_limit() {
    // A large decoded stream will exceed the cap mid-decode.
    let decoded = vec![0u8; 1024];
    let pdf = pdf_with_flate(&decoded, "<< /Predictor 15 /Colors 1 /Columns 1023 >>");
    let limits = Limits::default().with_max_stream_bytes(10);
    let doc = Document::from_bytes_with_limits(&pdf, limits).unwrap();
    let err = doc.page_contents(&doc.pages()[0]).unwrap_err();
    assert!(matches!(err, Error::LimitExceeded { .. }), "got: {err:?}");
}

/// /DecodeParms array longer than /Filter array is a structural error.
#[test]
fn decode_parms_length_mismatch() {
    let decoded = b"hi";
    let pdf = pdf_with_flate(
        decoded,
        "[null null]", // DecodeParms has 2 entries but Filter has 1
    );
    let err = decode_contents(&pdf).unwrap_err();
    assert!(matches!(err, Error::Structure(_)), "got: {err:?}");
}

/// After a failed decode, the shared budget is consumed (it is *not*
/// refunded); a second call with a valid stream still works if budget
/// remains.
#[test]
fn failed_decode_consumes_budget_consistently() {
    // One good stream (4 bytes) and one bad stream (unsupported filter).
    let good = b"good";
    let comp = {
        let mut e = ZlibEncoder::new(Vec::new(), Compression::default());
        e.write_all(good).unwrap();
        e.finish().unwrap()
    };
    let mut data = Vec::new();
    data.extend_from_slice(b"%PDF-1.4\n");
    let mut offsets = Vec::new();
    let bodies = [
        (1, b"<< /Type /Catalog /Pages 2 0 R >>".to_vec()),
        (
            2,
            b"<< /Type /Pages /Kids [3 0 R 6 0 R] /Count 2 >>".to_vec(),
        ),
        (
            3,
            b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 10 10] /Contents 4 0 R >>".to_vec(),
        ),
        (
            4,
            [
                format!(
                    "<< /Length {} /Filter /FlateDecode >>\nstream\n",
                    comp.len()
                )
                .into_bytes(),
                comp.clone(),
            ]
            .concat(),
        ),
        (
            6,
            b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 10 10] /Contents 7 0 R >>".to_vec(),
        ),
        (
            7,
            b"<< /Length 4 /Filter /JPXDecode >>\nstream\nbad!\nendstream".to_vec(),
        ),
    ];
    for (n, b) in &bodies {
        offsets.push((*n, data.len()));
        data.extend_from_slice(format!("{n} 0 obj\n").as_bytes());
        data.extend_from_slice(b);
        if *n == 4 {
            data.extend_from_slice(b"\nendstream\nendobj\n");
        } else {
            data.extend_from_slice(b"\nendobj\n");
        }
    }
    let xref = data.len();
    // Build a proper xref table: objects 0..7.
    let mut off_map = [0usize; 8];
    for (n, o) in &offsets {
        off_map[*n as usize] = *o;
    }
    data.extend_from_slice(b"xref\n0 8\n");
    data.extend_from_slice(b"0000000000 65535 f \n");
    for &off in off_map.iter().skip(1) {
        if off != 0 {
            data.extend_from_slice(format!("{off:010} 00000 n \n").as_bytes());
        } else {
            data.extend_from_slice(b"0000000000 00000 f \n");
        }
    }
    data.extend_from_slice(b"trailer\n<< /Size 8 /Root 1 0 R >>\n");
    data.extend_from_slice(format!("startxref\n{xref}\n%%EOF\n").as_bytes());

    let doc = Document::from_bytes(&data).unwrap();
    // Page 1: good stream (4 bytes decoded, budget now 4 spent).
    let c1 = doc.page_contents(&doc.pages()[0]).unwrap();
    assert_eq!(c1[0], good);
    // Page 2: unsupported filter — the decode attempt fails.  The budget
    // for the *attempted* decode is still consumed by policy (it guards
    // work done, not results kept), but the unsupported-filter error is
    // raised before decoding begins, so no bytes were charged.
    let err = doc.page_contents(&doc.pages()[1]).unwrap_err();
    assert!(matches!(err, Error::Unsupported { .. }), "got: {err:?}");
}
